export function initAIUsage({db,esc}){
 const menu=document.querySelector('#atlas-menu nav'),button=document.createElement('button');button.hidden=true;button.textContent='◷ Consumo de IA';menu.append(button);const dialog=document.createElement('dialog');dialog.className='poll-dialog';dialog.setAttribute('aria-label','Consumo de IA');document.body.append(dialog);let epoch=0;
 async function auth(session){const token=++epoch;button.hidden=true;dialog.close();if(!session?.user||session.user.is_anonymous)return;const r=await db.rpc('atlas_dev_poll_admin');if(token===epoch)button.hidden=!!r.error||r.data!==true;}
 button.onclick=()=>{document.querySelector('#atlas-menu').open=false;dialog.innerHTML='<button id="ai-close">Cerrar</button><h2>Consumo de IA</h2><p>Atlas dev · OpenAI directo · hora de Chile</p><label>Día<input id="ai-day" type="date"></label><button id="ai-refresh">Actualizar</button><div id="ai-stats" role="status"></div>';dialog.querySelector('#ai-day').value=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());dialog.querySelector('#ai-close').onclick=()=>dialog.close();dialog.querySelector('#ai-refresh').onclick=load;dialog.querySelector('#ai-day').onchange=load;dialog.showModal();load();};
 async function load(){const token=epoch,out=dialog.querySelector('#ai-stats');out.textContent='Consultando consumo…';try{const {data}=await db.auth.getSession();if(!data.session)throw Error();const response=await fetch('/.netlify/functions/ai-usage?day='+encodeURIComponent(dialog.querySelector('#ai-day').value),{headers:{Authorization:'Bearer '+data.session.access_token},cache:'no-store'});if(!response.ok)throw Error();const r=await response.json();if(token!==epoch||!dialog.open)return;const n=x=>Number(x).toLocaleString('es-CL');out.innerHTML=r.events===0?'<p>No hay registros de telemetría para este día. No equivale a consumo cero: el registro comienza con este despliegue.</p>':'<dl><dt>Llamadas registradas</dt><dd>'+n(r.calls)+' · '+n(r.success)+' correctas · '+n(r.errors)+' con error</dd><dt>Tokens de entrada / salida</dt><dd>'+n(r.inputTokens)+' / '+n(r.outputTokens)+'</dd><dt>Tokens de entrada cacheados por OpenAI</dt><dd>'+n(r.cachedTokens)+'</dd><dt>Costo estimado por tokens registrados (USD)</dt><dd>$'+Number(r.estimatedUSD).toFixed(6)+'</dd><dt>Solicitudes de síntesis resueltas por caché de Atlas</dt><dd>'+n(r.cacheHits)+' · '+(r.cacheRate===null?'sin proporción':(r.cacheRate*100).toFixed(1)+'%')+'</dd><dt>Generaciones de síntesis</dt><dd>'+n(r.generations)+'</dd></dl><p>'+n(r.unpriced)+' llamadas sin costo calculable; '+n(r.missingUsage)+' respuestas sin detalle de tokens.</p>'+(r.truncated?'<p>Consulta parcial: se alcanzó el máximo de 2.000 registros.</p>':'')+'<p>El ahorro por caché se mide en solicitudes que no necesitaron generación. No se convierte en dólares porque no conocemos el costo que habría tenido cada consulta.</p><p>El costo es una estimación con tokens reales; no es la factura ni descuenta créditos promocionales. No incluye alojamiento de Netlify ni respuestas servidas por la caché del navegador/CDN.</p><p>Tarifa GPT-4.1 mini revisada el '+esc(r.rateDate)+': USD 0,40 entrada, 0,10 entrada cacheada y 1,60 salida por millón de tokens. <a href="https://developers.openai.com/api/docs/models/gpt-4.1-mini" target="_blank" rel="noopener noreferrer">Fuente: OpenAI</a>.</p>';}catch{if(token===epoch)out.textContent='No se pudo consultar el consumo. Verifica tu sesión de administrador y reintenta.';}}
 db?.auth.getSession().then(({data})=>auth(data.session));db?.auth.onAuthStateChange((e,s)=>setTimeout(()=>auth(s),0));
}
